daxExpression:
// M expression — custom column to extract first word
Text.BeforeDelimiter([FullName], " ")

// Examples:
// "Alice Smith"  → "Alice"
// "Bob Van Dyke" → "Bob"
// "Carol"        → "Carol" (no space → returns full value)

// M language if/else — correct syntax
if [Region] = "US" then "No"
else if [Region] = "Canada" then "No"
else "Yes"

// Key differences from DAX:
// - lowercase "if", "then", "else"
// - no END keyword
// - nesting: else if (not ELSEIF)

// M custom function syntax — the "=>" arrow is required
let
    AddNumbers = (x, y) => x + y
in
    AddNumbers

// Calling it:
AddNumbers(3, 5)  // returns 8

// The "=>" separates the parameter list from the function body
